let currentLang = localStorage.getItem("talarico-lang") || (navigator.language?.toLowerCase().startsWith("es") ? "es" : "en");
if(!["en","es"].includes(currentLang)) currentLang="en";

const menuToggle = document.querySelector(".menu-toggle");
const primaryNav = document.getElementById("primary-nav");

function setMenu(open){
  primaryNav.classList.toggle("is-open",open);
  menuToggle.setAttribute("aria-expanded",String(open));
  menuToggle.setAttribute("aria-label", translations[currentLang][open ? "menuOpen" : "menuClosed"]);
}
menuToggle?.addEventListener("click",()=>setMenu(menuToggle.getAttribute("aria-expanded")!=="true"));
document.querySelectorAll('#primary-nav a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
window.addEventListener("resize",()=>{if(window.innerWidth>1050)setMenu(false)});

document.querySelectorAll('a[href^="#"]').forEach(a=>{
  a.addEventListener('click',e=>{
    const id=a.getAttribute('href');
    const target=id && id.length>1 ? document.querySelector(id) : null;
    if(target){
      e.preventDefault();
      target.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});
      history.replaceState(null,"",id);
    }
  });
});

const voteEls = {
  total: document.getElementById('vote-total'),yes:document.getElementById('vote-yes'),no:document.getElementById('vote-no'),
  absent:document.getElementById('vote-absent'),search:document.getElementById('vote-search'),session:document.getElementById('vote-session'),
  category:document.getElementById('vote-category'),value:document.getElementById('vote-value'),keyOnly:document.getElementById('vote-key-only'),
  status:document.getElementById('vote-status'),results:document.getElementById('vote-results')
};
let voteData={votes:[],sessions:[],categories:[]};

function t(key){return translations[currentLang][key] ?? translations.en[key] ?? key}
function escapeHtml(value=''){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]))}

function translateStatic(){
  document.documentElement.lang=currentLang;
  document.title=currentLang==="es" ? "Talarico Antes y Ahora | Archivo" : "Talarico Then & Now | Archive";
  document.querySelector('meta[name="description"]').setAttribute("content", currentLang==="es"
    ? "Comparación de archivo de los mensajes del sitio de campaña de James Talarico entre 2024 y 2026."
    : "An archival comparison of James Talarico campaign website messaging from 2024 through 2026.");
  document.querySelectorAll("[data-i18n]").forEach(el=>{
    const key=el.dataset.i18n;
    if(translations[currentLang][key]!==undefined) el.innerHTML=translations[currentLang][key];
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));
  document.querySelectorAll(".lang-btn").forEach(btn=>{
    const active=btn.dataset.lang===currentLang;
    btn.classList.toggle("is-active",active);
    btn.setAttribute("aria-pressed",String(active));
  });
  menuToggle?.setAttribute("aria-label",t("menuClosed"));
  renderCompare();
  renderIssueTrails();
}


function renderIssueTrails(){
  const container=document.getElementById("issue-trails");
  if(!container)return;
  const srcLabel=currentLang==="es"?"FUENTE":"SOURCE";
  container.innerHTML=issueTrails[currentLang].map(item=>`
    <article class="trail-card">
      <h3>${escapeHtml(item.title)}</h3>
      <div class="trail-stage"><span>2024</span><p>${escapeHtml(item.y2024)}</p><a href="${escapeHtml(item.src2024)}" target="_blank" rel="noopener">2024 ${srcLabel} →</a></div>
      <div class="trail-line" aria-hidden="true"></div>
      <div class="trail-stage"><span>2025</span><p>${escapeHtml(item.y2025)}</p><a href="${escapeHtml(item.src2025)}" target="_blank" rel="noopener">2025 ${srcLabel} →</a></div>
      <div class="trail-line" aria-hidden="true"></div>
      <div class="trail-stage"><span>2026</span><p>${escapeHtml(item.y2026)}</p><a href="${escapeHtml(item.src2026)}" target="_blank" rel="noopener">2026 ${srcLabel} →</a></div>
    </article>`).join("");
}

function renderCompare(){
  const body=document.getElementById("compare-body");
  if(!body)return;
  body.innerHTML=compareRows[currentLang].map(row=>`
    <tr>
      <th scope="row">${escapeHtml(row[0])}</th>
      <td>${escapeHtml(row[1])}</td>
      <td>${escapeHtml(row[2])}</td>
      <td>${escapeHtml(row[3])}</td>
    </tr>`).join("");
}

function prettyVote(value='unknown'){
  const keys={yes:"yesVote",no:"noVote",present_not_voting:"presentVote",absent:"absentVote",excused:"excusedVote",paired:"pairedVote",no_individual_record:"noRecordVote",unknown:"unknownVote"};
  return t(keys[value]||"unknownVote");
}
function translatedCategory(c){return currentLang==="es" ? (categoryTranslations[c]||c) : c}
function translatedSession(label){return currentLang==="es" ? (sessionTranslations[label]||label) : label}

function fillFilters(){
  const currentSession=voteEls.session?.value||"";
  const currentCategory=voteEls.category?.value||"";
  if(voteEls.session){
    voteEls.session.innerHTML=`<option value="">${escapeHtml(t("allSessions"))}</option>`;
    (voteData.sessions||[]).forEach(s=>{
      const o=document.createElement('option');o.value=s.code;o.textContent=translatedSession(s.label);voteEls.session.appendChild(o);
    });
    voteEls.session.value=currentSession;
  }
  if(voteEls.category){
    voteEls.category.innerHTML=`<option value="">${escapeHtml(t("allIssuesFilter"))}</option>`;
    (voteData.categories||[]).forEach(c=>{
      const o=document.createElement('option');o.value=c;o.textContent=translatedCategory(c);voteEls.category.appendChild(o);
    });
    voteEls.category.value=currentCategory;
  }
}
function updateStats(votes){
  if(!voteEls.total)return;
  voteEls.total.textContent=votes.length.toLocaleString(currentLang==="es"?"es-US":"en-US");
  voteEls.yes.textContent=votes.filter(v=>v.talarico_vote==="yes").length.toLocaleString();
  voteEls.no.textContent=votes.filter(v=>v.talarico_vote==="no").length.toLocaleString();
  voteEls.absent.textContent=votes.filter(v=>["absent","excused"].includes(v.talarico_vote)).length.toLocaleString();
}
function filteredVotes(){
  const q=(voteEls.search?.value||"").trim().toLowerCase(),session=voteEls.session?.value||"",category=voteEls.category?.value||"",value=voteEls.value?.value||"",keyOnly=Boolean(voteEls.keyOnly?.checked);
  return (voteData.votes||[]).filter(v=>{
    const haystack=[v.bill,v.description,v.category,v.action,v.session,v.notes].filter(Boolean).join(" ").toLowerCase();
    return (!q||haystack.includes(q))&&(!session||v.session===session)&&(!category||v.category===category)&&(!value||v.talarico_vote===value)&&(!keyOnly||v.key_vote===true);
  }).sort((a,b)=>(b.date||"").localeCompare(a.date||""));
}
function renderVotes(){
  if(!voteEls.results)return;
  const all=voteData.votes||[],votes=filteredVotes();updateStats(all);
  voteEls.status.textContent=`${t("showing")} ${votes.length.toLocaleString()} ${t("of")} ${all.length.toLocaleString()} ${t("verifiedRecords")}`;
  if(!votes.length){
    voteEls.results.innerHTML=`<div class="voteEmpty"><strong>${escapeHtml(t("noMatching"))}</strong><br>${escapeHtml(t("clearFilters"))}</div>`;return;
  }
  voteEls.results.innerHTML=votes.map(v=>{
    const official=v.official_source?`<a class="voteSource" href="${escapeHtml(v.official_source)}" target="_blank" rel="noopener">${escapeHtml(t("officialRecord"))}</a>`:"";
    const history=v.bill_history_source?`<a class="voteSource secondary" href="${escapeHtml(v.bill_history_source)}" target="_blank" rel="noopener">${escapeHtml(t("billHistory"))}</a>`:"";
    const cat=translatedCategory(v.category||"");
    const typeKey=v.record_type==="committee"?"committeeVote":v.record_type==="floor"?"floorVote":"otherVote";
    const desc=currentLang==="es"?(v.description_es||v.description):(v.description||v.action||t("recordedVote"));
    const action=currentLang==="es"?(v.action_es||v.action):(v.action||"");
    return `<article class="voteCard">
      <div><div class="voteBill">${escapeHtml(v.bill||t("record"))}</div><div class="voteMeta">${escapeHtml(v.session||"")} ${v.date?"· "+escapeHtml(v.date):""}</div></div>
      <div>
        <div class="record-badges"><span class="record-badge type">${escapeHtml(t(typeKey))}</span>${v.verified===true?`<span class="record-badge verified">${escapeHtml(t("verifiedBadge"))}</span>`:""}</div>
        <h3>${escapeHtml(desc)}</h3>${action?`<p><strong>${escapeHtml(t("action"))}</strong> ${escapeHtml(action)}</p>`:""}
        <div class="voteTags">${cat?`<span class="voteTag">${escapeHtml(cat)}</span>`:""}${v.result?`<span class="voteTag">${escapeHtml(t("result"))}: ${escapeHtml(String(v.result).toUpperCase())}</span>`:""}${v.key_vote===true?`<span class="voteTag">${escapeHtml(t("keyVote"))}</span>`:""}</div>
        <div class="vote-source-row">${official}${history}</div>
      </div>
      <div class="voteChoice ${escapeHtml(v.talarico_vote||"unknown")}">${escapeHtml(prettyVote(v.talarico_vote))}</div>
    </article>`;
  }).join("");
}
["input","change"].forEach(evt=>[voteEls.search,voteEls.session,voteEls.category,voteEls.value,voteEls.keyOnly].forEach(el=>el?.addEventListener(evt,renderVotes)));

async function loadVotes(){
  if(!voteEls.results)return;
  try{
    const res=await fetch("data/talarico-votes.json",{cache:"no-store"});if(!res.ok)throw new Error(`HTTP ${res.status}`);
    voteData=await res.json();fillFilters();renderVotes();
  }catch(err){
    voteEls.status.textContent=t("loadError");
    voteEls.results.innerHTML=`<div class="voteEmpty"><strong>${escapeHtml(t("couldNotLoad"))}</strong><br>${escapeHtml(t("fileCheck"))} ${escapeHtml(err.message)}</div>`;
    console.error("Voting data load failed:",err);
  }
}


let researchData={scorecard_inventory:[],verified_crosschecks:[]};

const scorecardTopicES={
  "Economy / business":"Economía / negocios",
  "Environment":"Medio ambiente",
  "Taxes / spending / property":"Impuestos / gasto / propiedad",
  "Reproductive policy":"Política reproductiva",
  "Social issues":"Temas sociales",
  "Conservative / limited government":"Conservador / gobierno limitado",
  "General / ideological":"General / ideológico"
};

function renderScorecards(){
  const holder=document.getElementById("scorecard-groups");
  if(!holder)return;
  const items=researchData.scorecard_inventory||[];
  const years=[...new Set(items.map(x=>x.year))].sort((a,b)=>b-a);
  const total=document.getElementById("scorecard-total"), yearCount=document.getElementById("scorecard-years"), cross=document.getElementById("crosschecks-total");
  if(total)total.textContent=items.length.toLocaleString();
  if(yearCount)yearCount.textContent=years.length.toLocaleString();
  if(cross)cross.textContent=(researchData.verified_crosschecks||[]).length.toLocaleString();

  holder.innerHTML=years.map(year=>{
    const rows=items.filter(x=>x.year===year);
    return `<section class="scorecardYear" aria-labelledby="scorecard-year-${year}">
      <div class="scorecardYearHead"><h3 id="scorecard-year-${year}">${year}</h3><span>${rows.length} ${escapeHtml(t("scorecardsFound"))}</span></div>
      <div class="scorecardList">${rows.map(x=>`
        <article class="scorecardItem">
          <strong>${escapeHtml(x.organization)}</strong>
          <small>${escapeHtml(currentLang==="es"?(scorecardTopicES[x.topic]||x.topic):x.topic)}</small>
          <a href="${escapeHtml(x.url)}" target="_blank" rel="noopener">${escapeHtml(t("openScorecard"))}</a>
        </article>`).join("")}
      </div>
    </section>`;
  }).join("");
}

async function loadResearch(){
  try{
    const res=await fetch("data/talarico-research.json",{cache:"no-store"});
    if(!res.ok)throw new Error(`HTTP ${res.status}`);
    researchData=await res.json();
    renderScorecards();
  }catch(err){
    const holder=document.getElementById("scorecard-groups");
    if(holder)holder.innerHTML=`<div class="voteEmpty"><strong>${escapeHtml(t("researchLoadError"))}</strong><br>${escapeHtml(err.message)}</div>`;
    console.error("Research data load failed:",err);
  }
}

document.querySelectorAll(".lang-btn").forEach(btn=>btn.addEventListener("click",()=>{
  currentLang=btn.dataset.lang;localStorage.setItem("talarico-lang",currentLang);translateStatic();fillFilters();renderVotes();renderScorecards();
}));
translateStatic();
loadVotes();
loadResearch();
